import numpy as np
from numba import njit
from typing import Any

@njit("float64[:](float64[:])", cache=True)
def project_simplex(y):
    sorted_y = np.sort(y)
    S = 0.0
    theta = 0.0
    n = len(y)
    for i in range(n):
        val = sorted_y[n - 1 - i]
        S += val
        t = (S - 1.0) / (i + 1.0)
        if val > t:
            theta = t
        else:
            break

    x = np.empty_like(y)
    for i in range(n):
        val = y[i] - theta
        x[i] = val if val > 0 else 0.0
    return x

class Solver:
    def __init__(self):
        # Warmup the JIT to ensure it doesn't compile during the first call
        project_simplex(np.array([1.0, 2.0], dtype=np.float64))

    def solve(self, problem: dict[str, Any], **kwargs) -> dict[str, Any]:
        y = np.array(problem["y"], dtype=np.float64).flatten()
        x = project_simplex(y)
        return {"solution": x}

